#include "MainComponent.h"
#include <cmath>
namespace {
juce::String u(const char* s){return juce::String::fromUTF8(s);}
juce::String token(const StudioTrack& track){return track.file.getFullPathName()+"|"+juce::String(track.trimIn,9)+"|"+juce::String(track.trimOut,9);}
juce::String rangeText(double low,double high){return juce::String(vocal::octaveNote(low))+u(" – ")+juce::String(vocal::octaveNote(high));}
}
void StudioMain::loadVoicePreference(){if(engine.voiceProfile.valid)return;const auto state=juce::JSON::parse(preferences.getUserSettings()->getValue("voiceProfile"));const double low=static_cast<double>(state["low"]),high=static_cast<double>(state["high"]),median=static_cast<double>(state["median"]);if(static_cast<bool>(state["valid"])&&std::isfinite(low)&&std::isfinite(high)&&std::isfinite(median)&&low>=33&&high<=96&&high-low>=4&&high-low<=48)engine.voiceProfile={true,low,high,median,static_cast<double>(state["seconds"])};}
void StudioMain::learnVoiceFromSelected(){if(!canEdit()||selected<0)return;const int index=selected;if(!engine.getTracks()[static_cast<std::size_t>(index)]->vocal){fitStatus=u("Chọn bản giọng của chính bạn, bật Track giọng hát. Đừng dùng beat hoặc vocal ca sĩ khác làm hồ sơ giọng.");return;}setBusy(true,u("Đang đo quãng hát thoải mái từ giọng của bạn…"));cancelExport=false;exportProgress=0;auto analysis=std::make_shared<vocal::PitchAnalysis>();auto result=std::make_shared<juce::Result>(juce::Result::ok());juce::Component::SafePointer<StudioMain> safe(this);runJob([this,index,analysis,result]{*result=engine.analyseTrack(index,*analysis,cancelExport,exportProgress);},[safe,analysis,result]{if(!safe)return;if(result->failed()){safe->fitStatus=result->getErrorMessage();return;}const auto profile=vocal::measureComfortableRange(*analysis);if(!profile.valid){safe->fitStatus=u("Mẫu chưa đủ: cần ít nhất 2 giây có giọng rõ, nhiều nốt cách nhau ít nhất 4 bán âm, không vỡ nặng. Hát từ thấp đến cao trong vùng thoải mái; không cố gằn. Hồ sơ cũ được giữ nguyên.");return;}safe->engine.voiceProfile=profile;safe->fitPlan.reset();auto* state=new juce::DynamicObject;state->setProperty("valid",true);state->setProperty("low",profile.lowMidi);state->setProperty("high",profile.highMidi);state->setProperty("median",profile.medianMidi);state->setProperty("seconds",profile.voicedSeconds);safe->preferences.getUserSettings()->setValue("voiceProfile",juce::JSON::toString(juce::var(state)));safe->preferences.saveIfNeeded();safe->save();safe->fitStatus=u("Đã đo vùng hát thoải mái: ")+rangeText(profile.lowMidi,profile.highMidi)+u(". Chọn beat và vocal mẫu/giai điệu của bài để đề xuất tone.");safe->status(u("Đã lưu hồ sơ giọng trên máy và trong dự án."));});}
void StudioMain::recordVoiceSample(){if(!canEdit())return;engine.calibrationInputOnly=true;const auto started=engine.startRecording(engine.session().getChildFile("Audio"));if(started.failed()){engine.calibrationInputOnly=false;fitStatus=started.getErrorMessage();return;}calibrating=true;calibrationDeadline=juce::Time::getMillisecondCounterHiRes()+20000;fitStatus=u("ĐANG THU MẪU 20 GIÂY · Hát ngân từ thấp đến cao trong quãng thoải mái, dùng tai nghe, không gằn hay cố lên nốt. Tạm bỏ qua beat/vang/Antares để đo giọng gốc. Bấm Dừng để kết thúc sớm.");save();status(fitStatus);}
void StudioMain::finishCalibration(bool success){engine.calibrationInputOnly=false;calibrating=false;calibrationDeadline=0;if(success&&!closing)learnVoiceFromSelected();else fitStatus=u("Đã dừng đo giọng. Bản thu được giữ lại; hồ sơ giọng cũ không thay đổi.");}
void StudioMain::planSongFit(int beat,int melody,bool allBacking){if(!canEdit())return;const auto& tracks=engine.getTracks();if(!engine.voiceProfile.valid){fitStatus=u("Đo giọng của bạn trước bằng micro hoặc track giọng đã thu.");return;}if(!juce::isPositiveAndBelow(beat,static_cast<int>(tracks.size()))||tracks[static_cast<std::size_t>(beat)]->vocal||!juce::isPositiveAndBelow(melody,static_cast<int>(tracks.size()))||!tracks[static_cast<std::size_t>(melody)]->vocal){fitStatus=u("Chọn beat và một vocal mẫu/humming giai điệu riêng. Không thể suy ra quãng giai điệu hát từ nốt bass của beat.");return;}auto plan=std::make_shared<SongFitPlan>();plan->profile=engine.voiceProfile;plan->melody=melody;plan->melodyToken=token(*tracks[static_cast<std::size_t>(melody)]);for(int i=0;i<static_cast<int>(tracks.size());++i)if((i==beat||(allBacking&&!tracks[static_cast<std::size_t>(i)]->vocal&&!tracks[static_cast<std::size_t>(i)]->mute.load()))){plan->beats.push_back(i);plan->beatTokens.push_back(token(*tracks[static_cast<std::size_t>(i)]));}setBusy(true,u("Đang so giai điệu bài với quãng giọng của bạn…"));cancelExport=false;exportProgress=0;auto result=std::make_shared<juce::Result>(juce::Result::ok());juce::Component::SafePointer<StudioMain> safe(this);runJob([this,beat,melody,plan,result]{vocal::PitchAnalysis tune,key;*result=engine.analyseTrack(melody,tune,cancelExport,exportProgress);if(result->failed())return;plan->fit=vocal::fitSongToVoice(plan->profile,tune);if(!plan->fit.valid){*result=juce::Result::fail(u("Vocal mẫu chưa có đủ nốt rõ để so quãng. Dùng vocal riêng hoặc humming theo đúng giai điệu bài."));return;}*result=engine.analyseTrack(beat,key,cancelExport,exportProgress);if(result->failed())return;if(key.tonic>=0&&key.keyConfidence>=.5){plan->tonic=(key.tonic+plan->fit.semitones+24)%12;plan->minor=key.minor;}},[safe,plan,result]{if(!safe)return;if(result->failed()){safe->fitStatus=result->getErrorMessage();safe->fitPlan.reset();return;}safe->fitPlan=plan;const auto& fit=plan->fit;safe->fitStatus=u("Quãng của bạn: ")+rangeText(plan->profile.lowMidi,plan->profile.highMidi)+u(" · Giai điệu mẫu: ")+rangeText(fit.melodyLow,fit.melodyHigh)+u("\nĐề xuất beat: ")+(fit.semitones>0?"+":"")+juce::String(fit.semitones)+u(" bán âm; hát lệch bản mẫu ")+juce::String(fit.singingOctaves)+u(" quãng tám. Đích: ")+rangeText(fit.targetLow,fit.targetHigh);safe->fitStatus+=fit.fits?u("\nPhù hợp vùng đã đo. Nghe thử và tự xác nhận cảm giác thoải mái trước khi thu."):u("\nCHƯA KHỚP: vượt vùng đã đo trong mức chuyển này. Không tự áp dụng; đo lại, hát đổi quãng tám theo câu hoặc chọn bài khác.");if(plan->tonic>=0)safe->fitStatus+=u("\nTone sau chuyển: ")+juce::String(vocal::noteName(60+plan->tonic))+(plan->minor?" minor":" major");else safe->fitStatus+=u("\nTone trưởng/thứ chưa rõ: không tự gửi Key/Scale; chọn tay trong tab Antares.");safe->status(u("Đã tính đề xuất theo giọng của bạn; chưa đổi audio."));});}
void StudioMain::applySongFitPlan(){if(!canEdit()||!fitPlan)return;const auto plan=fitPlan;if(!plan->fit.fits){fitStatus=u("Đề xuất chưa nằm trong vùng thoải mái; không tự đổi bài.");return;}const auto& tracks=engine.getTracks();if(!juce::isPositiveAndBelow(plan->melody,static_cast<int>(tracks.size()))||token(*tracks[static_cast<std::size_t>(plan->melody)])!=plan->melodyToken||engine.voiceProfile.lowMidi!=plan->profile.lowMidi||engine.voiceProfile.highMidi!=plan->profile.highMidi){fitStatus=u("Mẫu giọng/giai điệu đã đổi. Dò đề xuất lại trước khi áp dụng.");return;}for(std::size_t i=0;i<plan->beats.size();++i)if(!juce::isPositiveAndBelow(plan->beats[i],static_cast<int>(tracks.size()))||token(*tracks[static_cast<std::size_t>(plan->beats[i])])!=plan->beatTokens[i]){fitStatus=u("Beat đã đổi. Tính đề xuất lại.");return;}setBusy(true,u("Đang đổi beat theo quãng giọng, giữ tempo và file gốc…"));cancelExport=false;exportProgress=0;struct Batch {juce::Result result=juce::Result::ok();std::vector<std::pair<int,std::unique_ptr<StudioTrack>>> tracks;};auto batch=std::make_shared<Batch>();juce::Component::SafePointer<StudioMain> safe(this);runJob([this,plan,batch]{if(plan->fit.semitones==0)return;for(int i:plan->beats){std::unique_ptr<StudioTrack> output;vocal::PitchOptions options;options.semitones=static_cast<float>(plan->fit.semitones);options.preserveFormants=false;batch->result=engine.renderPitchTrack(i,options,output,cancelExport,exportProgress);if(batch->result.failed())return;batch->tracks.emplace_back(i,std::move(output));}},[safe,plan,batch]{if(!safe)return;if(batch->result.failed()||safe->cancelExport.load()){safe->fitStatus=batch->result.failed()?batch->result.getErrorMessage():u("Đã hủy, beat đang dùng không thay đổi.");return;}safe->engine.replaceTracks(std::move(batch->tracks));safe->engine.getTracks()[static_cast<std::size_t>(plan->melody)]->mute=true;safe->undo.clear();safe->redo.clear();safe->pitchAnalysis.reset();safe->fitPlan.reset();safe->refreshTracks();safe->refreshInspector();if(plan->tonic>=0)safe->engine.setSongKey(plan->tonic,plan->minor,u("Beat đã chuyển theo quãng giọng"));else{safe->engine.setSongKey(-1,false,u("Beat đã chuyển nhưng chưa rõ tone"));}safe->save();safe->fitStatus=u("Đã đổi các beat được chọn theo giọng của bạn, giữ tempo. Vocal mẫu đã mute; quãng tám hát gợi ý: ")+juce::String(plan->fit.singingOctaves)+u(". Bật kiểm âm FX để hát qua Antares. Bản gốc còn nguyên.");safe->status(safe->fitStatus);});}

void StudioMain::setComfortableRange(double low,double high){if(!canEdit()||!std::isfinite(low)||!std::isfinite(high)||low<33||high>96||high-low<4||high-low>48){fitStatus=u("Chọn vùng ít nhất 4 bán âm, nốt cao lớn hơn nốt thấp.");return;}engine.voiceProfile={true,low,high,(low+high)*.5,0};fitPlan.reset();auto* state=new juce::DynamicObject;state->setProperty("valid",true);state->setProperty("low",low);state->setProperty("high",high);state->setProperty("median",(low+high)*.5);state->setProperty("seconds",0);preferences.getUserSettings()->setValue("voiceProfile",juce::JSON::toString(juce::var(state)));preferences.saveIfNeeded();save();fitStatus=u("Đã lưu vùng thoải mái bạn tự chọn. Chọn giai điệu bài và beat để tính đề xuất.");}
